var a=[{title:`Allenarsi con il caldo`,text:`Caldo e umidità possono far sembrare molto più difficile una sessione facile. Scegli le ore più fresche e percorsi all’ombra, inizia con calma e bevi abbastanza per le condizioni. Il CDC consiglia di fermarsi e spostarsi in un luogo fresco se ti senti svenire o debole. Confusione, collasso o sospetto colpo di calore richiedono aiuto di emergenza.`},{title:`Giornate fredde, bagnate e ventose`,text:`Indossa strati che puoi togliere e copri la pelle esposta quando fa freddo. Pioggia e sudore possono rendere pericolosamente freddi vestiti e superfici, e il freddo intenso può causare congelamento o ipotermia. Ghiaccio o scarsa visibilità sono un buon motivo per allenarti al chiuso quel giorno.`},{title:`Controlla il terreno`,text:`Cerca buche, ghiaia sciolta, radici, marciapiedi irregolari, scarsa illuminazione e attraversamenti stradali. Le pendenze cambiano il carico su muscoli e articolazioni. Su un percorso nuovo, parti a un ritmo comodo, evita gli scatti al massimo e indossa scarpe con buona aderenza per la superficie.`},{title:`Controlla le attrezzature del parco`,text:`Panche, ringhiere e sbarre per trazioni possono essere rovinate dalle intemperie, allentate o non costruite per esercizi dinamici. Cerca bordi affilati, ruggine, raccordi rotti e supporti traballanti. Non appenderti a nulla che non sia chiaramente costruito per reggerti. Lascia molto spazio a ciclisti, bambini e altri frequentatori del parco.`},{title:`Ricontrolla ogni volta`,text:`Le condizioni all’aperto cambiano, quindi ricontrolla ogni volta che esci. Con maltempo pericoloso, passa a una sessione al chiuso o a basso impatto, e scegli percorsi e movimenti adatti alla luce, al terreno e alla tua esperienza.`}];var o=[{label:`CDC: allenarsi con il caldo`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`},{label:`CDC: prevenire congelamento e ipotermia`,url:`https://www.cdc.gov/winter-weather/prevention/preventing-frostbite.html`},{label:`CDC: raccomandazioni sull’attività fisica per gli adulti`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};